import { useCallback, useRef } from 'react'
import { Button } from '..'
import { DisplayFlexCCC, Grid } from '../../commonStyle/index.style'
import { ARROW_RIGHT_ICON, TRASH_ICON, CAMERA_BLACK } from '../../images/imageUrl'
import { ImageViewerStyle, CarouselArrowStyle } from './index.style'
import { LANG_STRINGS } from '../../lang/index'
import 'react-responsive-carousel/lib/styles/carousel.min.css'
import { Carousel } from 'react-responsive-carousel'
import ReactModal from 'react-responsive-modal'
import { isMobileView } from '../../helpers/utility'
import { AgentColorPallette } from '../../configs/colorPallete'
import { INPUT_FILE_TYPE } from '../../constants/file'

const TRANSPARENT_MODAL = {
  modal: {
    padding: 0,
    width: '100%',
    maxWidth: isMobileView() ? '100%' : '450px',
    backgroundColor: '#0000009e',
    height: '100%',
  },
  overlay: {
    padding: 0,
    width: '100%',
    // maxWidth: 400
  },
  closeButton: {
    padding: '8px',
    color: '#ffffff',
    top: 0,
    zIndex: 10,
  },
}

function ImageViewer({
  show,
  data = [],
  showBtn = false,
  fileType,
  activeIndex,
  viewerImg,
  onDelete = () => {},
  onClose = () => {},
  onChange = () => {},
}) {
  const that = useRef({
    modelChangeStyles: TRANSPARENT_MODAL,
    selected: activeIndex || 0,
  })

  const handleOnChange = useCallback((index, item) => {
    that.current.selected = index
  }, [])

  const handleDelete = useCallback(() => {
    onDelete(that.current.selected, viewerImg.name)
  }, [onDelete, viewerImg])

  const handleImgChange = useCallback(
    (e) => {
      onChange(e, 'image_viewer', that.current.selected)
    },
    [onChange]
  )

  return show ? (
    <ReactModal
      open={show}
      styles={that.current.modelChangeStyles}
      classNames={{
        closeButton: 'modal-white-btn',
      }}
      showCloseIcon
      onClose={onClose}
      focusTrapped={false}
      blockScroll
      closeIconSize={22}
      center
    >
      <ImageViewerStyle>
        {!Array.isArray(viewerImg?.url) ? (
          <DisplayFlexCCC className="viewer-single-img">
            <DisplayFlexCCC key={viewerImg.filename} className="viewer-img">
              <img src={viewerImg.url} alt="" />
            </DisplayFlexCCC>
          </DisplayFlexCCC>
        ) : (
          <Carousel
            showThumbs={false}
            showStatus={false}
            showArrows
            showIndicators={false}
            className="image-viewer-carousel"
            onChange={handleOnChange}
            selectedItem={activeIndex}
            renderArrowPrev={(onClickHandler, hasPrev, label) =>
              hasPrev && (
                <CarouselArrowStyle
                  left="15px"
                  type="button"
                  onClick={onClickHandler}
                  title={label}
                >
                  <img className="arrow-left" src={ARROW_RIGHT_ICON} alt="" />
                </CarouselArrowStyle>
              )
            }
            renderArrowNext={(onClickHandler, hasNext, label) =>
              hasNext && (
                <CarouselArrowStyle
                  right="15px"
                  type="button"
                  onClick={onClickHandler}
                  title={label}
                >
                  <img src={ARROW_RIGHT_ICON} alt="" />
                </CarouselArrowStyle>
              )
            }
          >
            {data.map((item) => (
              <DisplayFlexCCC className="viewer-img" key={item.filename}>
                <img src={item.url} alt="" />
              </DisplayFlexCCC>
            ))}
          </Carousel>
        )}
        {showBtn && (
          <Grid gridColumn="1fr 1fr" className="img-view-actions">
            <Button
              backgroundColor={AgentColorPallette.white}
              color={AgentColorPallette.blackGrey}
              width="60%"
              className="justify-self-center"
              onClick={handleDelete}
            >
              <img src={TRASH_ICON} alt="Delete" width={20} />
              &nbsp;&nbsp;
              <span>{LANG_STRINGS.remove}</span>
            </Button>
            <Button
              backgroundColor={AgentColorPallette.white}
              color={AgentColorPallette.blackGrey}
              width="60%"
              className="justify-self-center change-view-img"
            >
              <img src={CAMERA_BLACK} alt="Change" width={20} />
              &nbsp;&nbsp;
              <span>{LANG_STRINGS.changeGani}</span>
              <input
                type="file"
                id="image_viewer"
                name="image_viewer"
                onChange={(e) => handleImgChange(e)}
                className="upload-file-input"
                accept={fileType || INPUT_FILE_TYPE.IMAGE}
              />
            </Button>
          </Grid>
        )}
      </ImageViewerStyle>
    </ReactModal>
  ) : null
}

export default ImageViewer
